public class CollectionScopeProbe62 {
    private static List<Object> storedItems;
    public static List<Object> items {
        get {
            if (storedItems == null) storedItems = new List<Object>();
            return storedItems;
        }
        set { storedItems = value; }
    }
    public static String label = 'outer-scalar';

    public class Worker {
        private final List<Object> items;
        private final String label;
        public Worker() {
            this.items = new List<Object>{'inner-list'};
            this.label = 'inner-scalar';
        }
        public Map<String, Object> direct() {
            return new Map<String, Object>{
                'qualifiedList' => JSON.serialize(CollectionScopeProbe62.items),
                'instanceList' => JSON.serialize(this.items),
                'qualifiedScalar' => CollectionScopeProbe62.label,
                'instanceScalar' => this.label
            };
        }
        public Integer build() {
            List<Object> saved = new List<Object>(CollectionScopeProbe62.items);
            try {
                CollectionScopeProbe62.items.addAll(this.items);
                return CollectionScopeProbe62.items.size();
            } finally {
                CollectionScopeProbe62.items.clear();
                CollectionScopeProbe62.items.addAll(saved);
            }
        }
        public String instanceItems() {
            return JSON.serialize(this.items);
        }
        public Map<String, Object> cleanup(Boolean raiseInside) {
            Map<String, Object> row = new Map<String, Object>();
            List<Object> saved = CollectionScopeProbe62.items;
            try {
                CollectionScopeProbe62.items = new List<Object>{'temporary-list'};
                row.put('duringQualifiedList', JSON.serialize(CollectionScopeProbe62.items));
                row.put('duringInstanceList', JSON.serialize(this.items));
                if (raiseInside) throw new IllegalArgumentException('owned-cleanup');
                row.put('caught', false);
            } catch (IllegalArgumentException error) {
                row.put('caught', true);
            } finally {
                CollectionScopeProbe62.items = saved;
            }
            row.put('restoredQualifiedList', JSON.serialize(CollectionScopeProbe62.items));
            row.put('restoredInstanceList', JSON.serialize(this.items));
            return row;
        }
    }

    public class RenamedWorker {
        private final List<Object> localItems;
        private final String localLabel;
        public RenamedWorker() {
            this.localItems = new List<Object>{'renamed-inner-list'};
            this.localLabel = 'renamed-inner-scalar';
        }
        public Map<String, Object> direct() {
            return new Map<String, Object>{
                'qualifiedList' => JSON.serialize(CollectionScopeProbe62.items),
                'instanceList' => JSON.serialize(this.localItems),
                'qualifiedScalar' => CollectionScopeProbe62.label,
                'instanceScalar' => this.localLabel
            };
        }
    }

    public static String observe() {
        Map<String, Object> rows = new Map<String, Object>();
        Worker worker = new Worker();
        CollectionScopeProbe62.items = new List<Object>{'outer-list'};
        CollectionScopeProbe62.label = 'outer-scalar';
        try {
            rows.put('direct', worker.direct());
        } catch (Exception error) {
            rows.put('directError', error.getTypeName() + ': ' + error.getMessage());
        }
        CollectionScopeProbe62.items = new List<Object>{'outer-list'};
        try {
            rows.put('normalFinally', worker.cleanup(false));
        } catch (Exception error) {
            rows.put('normalFinallyError', error.getTypeName() + ': ' + error.getMessage());
        }
        CollectionScopeProbe62.items = new List<Object>{'outer-list'};
        try {
            rows.put('exceptionFinally', worker.cleanup(true));
        } catch (Exception error) {
            rows.put('exceptionFinallyError', error.getTypeName() + ': ' + error.getMessage());
        }
        CollectionScopeProbe62.items = new List<Object>{'outer-list'};
        try {
            rows.put('renamedControl', new RenamedWorker().direct());
        } catch (Exception error) {
            rows.put('renamedControlError', error.getTypeName() + ': ' + error.getMessage());
        }
        CollectionScopeProbe62.items = new List<Object>();
        try {
            Integer count = worker.build();
            rows.put('buildEmpty', new Map<String, Object>{
                'returnedSize' => count,
                'finalOuter' => JSON.serialize(CollectionScopeProbe62.items),
                'inner' => worker.instanceItems()
            });
        } catch (Exception error) {
            rows.put('buildEmptyError', error.getTypeName() + ': ' + error.getMessage());
        }
        CollectionScopeProbe62.items = new List<Object>{'outer-list'};
        try {
            Integer count = worker.build();
            rows.put('buildSeeded', new Map<String, Object>{
                'returnedSize' => count,
                'finalOuter' => JSON.serialize(CollectionScopeProbe62.items),
                'inner' => worker.instanceItems()
            });
        } catch (Exception error) {
            rows.put('buildSeededError', error.getTypeName() + ': ' + error.getMessage());
        }
        rows.put('outerAfter', JSON.serialize(CollectionScopeProbe62.items));
        return JSON.serialize(rows);
    }
}

